28	function isTrustedRendererLocation(candidateUrl, trustedLocation) {
29	    try {
30	        const candidate = new URL(candidateUrl);
31	        const trusted = new URL(trustedLocation);
32	        candidate.hash = '';
33	        trusted.hash = '';
34	
35	        return candidate.href === trusted.href;
36	    } catch {
37	        return false;
38	    }
39	}
