2	const { pathToFileURL } = require('node:url');
3	const { app, BrowserWindow } = require('electron');
4	const { registerNavigationGuards } = require('../shell/renderer_security');
5	
6	const NAVIGATION_SETTLE_MS = 100;
7	const NAVIGATION_TIMEOUT_MS = 5000;
8	
9	function wait(duration) {
10	    return new Promise((resolve) => setTimeout(resolve, duration));
11	}
12	
13	function waitForFrameNavigation(webContents) {
14	    return new Promise((resolve, reject) => {
15	        const timeout = setTimeout(() => reject(new Error('Timed out waiting for frame navigation')), NAVIGATION_TIMEOUT_MS);
16	        webContents.once('will-frame-navigate', ({ url }) => {
17	            clearTimeout(timeout);
18	            resolve(url);
19	        });
20	    });
21	}
22	
23	async function ignoreExternalUrl() {}
24	
25	async function runNavigationRegression() {
26	    const fixturesDirectory = path.join(__dirname, 'fixtures');
27	    const trustedPath = path.join(fixturesDirectory, 'trusted_navigation.html');
28	    const untrustedPath = path.join(fixturesDirectory, 'untrusted_navigation.html');
29	    const trustedLocation = pathToFileURL(trustedPath).href;
30	    const untrustedLocation = pathToFileURL(untrustedPath).href;
31	    const window = new BrowserWindow({
32	        show: false,
33	        webPreferences: { contextIsolation: true, nodeIntegration: false, sandbox: true },
34	    });
35	    registerNavigationGuards(window.webContents, trustedLocation, ignoreExternalUrl);
36	    await window.loadFile(trustedPath);
37	    await window.webContents.executeJavaScript(`
38	        document.querySelector('#draft').value = 'unsaved change';
39	        document.querySelector('#file-link').href = ${JSON.stringify(untrustedLocation)};
40	    `);
41	    const navigationAttempt = waitForFrameNavigation(window.webContents);
42	    await window.webContents.executeJavaScript("document.querySelector('#file-link').click()");
43	    const attemptedLocation = await navigationAttempt;
44	    await wait(NAVIGATION_SETTLE_MS);
45	    const state = await window.webContents.executeJavaScript(`({
46	        draft: document.querySelector('#draft').value,
47	        location: window.location.href,
48	        marker: document.querySelector('#app-state').textContent,
49	    })`);
50	
51	    if (attemptedLocation !== untrustedLocation) throw new Error(`Unexpected navigation target: ${attemptedLocation}`);
52	    if (state.location !== trustedLocation) throw new Error(`Trusted renderer was replaced by: ${state.location}`);
53	    if (state.marker !== 'trusted-renderer') throw new Error('Trusted renderer DOM was replaced');
54	    if (state.draft !== 'unsaved change') throw new Error('Unsaved renderer state was lost');
55	
56	    window.destroy();
57	}
58	
59	async function main() {
60	    try {
61	        await app.whenReady();
62	        await runNavigationRegression();
63	        console.log('navigation-regression-passed');
64	        app.quit();
65	    } catch (error) {
66	        console.error(error);
67	        app.exit(1);
68	    }
69	}
