8	function resolveSegments(sourcePath: string, linkPath: string) {
9	    const sourceSegments = normalizePath(sourcePath).split('/');
10	    sourceSegments.pop();
11	    const segments = linkPath.startsWith('/') ? [] : sourceSegments;
12	    const linkSegments = normalizePath(linkPath).replace(/^\/+/, '').split('/');
13	
14	    for (const segment of linkSegments) {
15	        if (!segment || segment === '.') continue;
16	        if (segment === '..') {
17	            if (segments.length === 0) return null;
18	            segments.pop();
19	            continue;
20	        }
21	        segments.push(segment);
22	    }
23	
24	    return segments.join('/');
25	}
