27	function decodeFileUrl(href: string) {
28	    try {
29	        const url = new URL(href);
30	        if (url.protocol !== 'file:' || url.search || url.hash) return null;
31	
32	        const pathname = decodeURIComponent(url.pathname);
33	        if (url.hostname) return normalizePath(`//${url.hostname}${pathname}`);
34	
35	        return normalizePath(/^\/[a-z]:\//iu.test(pathname) ? pathname.slice(1) : pathname);
36	    } catch {
37	        return null;
38	    }
39	}
