41	function decodeAbsolutePath(href: string) {
42	    const fileUrlPath = href.toLowerCase().startsWith('file:') ? decodeFileUrl(href) : null;
43	    if (fileUrlPath) return fileUrlPath;
44	
45	    let decodedPath: string;
46	    try {
47	        decodedPath = decodeURIComponent(href);
48	    } catch {
49	        return null;
50	    }
51	
52	    const normalizedPath = normalizePath(decodedPath);
53	    if (/^[a-z]:\//iu.test(normalizedPath) || normalizedPath.startsWith('//')) return normalizedPath;
54	
55	    return null;
56	}
