58	function projectPathFromAbsolutePath(absolutePath: string, projectRootPath: string | null) {
59	    if (!projectRootPath) return null;
60	
61	    const normalizedRootPath = normalizePath(projectRootPath).replace(/\/+$/u, '');
62	    const normalizedAbsolutePath = normalizePath(absolutePath);
63	    const rootPrefix = `${normalizedRootPath}/`;
64	    if (!normalizedAbsolutePath.toLowerCase().startsWith(rootPrefix.toLowerCase())) return null;
65	
66	    return normalizedAbsolutePath.slice(rootPrefix.length);
67	}
