69	function projectTarget(path: string, repositoryPaths: readonly string[]): JsonLinkTarget {
70	    const normalizedPath = normalizePath(path);
71	    const repositoryPath = repositoryPaths.find((candidate) => (
72	        normalizePath(candidate).toLowerCase() === normalizedPath.toLowerCase()
73	    ));
74	
75	    return { kind: 'project', path: repositoryPath ?? normalizedPath };
76	}
