79	export function resolveJsonLink(
80	    sourcePath: string,
81	    href: string,
82	    projectRootPath: string | null,
83	    repositoryPaths: readonly string[],
84	): JsonLinkTarget | null {
85	    const trimmedHref = href.trim();
86	    if (!trimmedHref || trimmedHref.startsWith('#')) return null;
87	    if (trimmedHref.includes('?') || trimmedHref.includes('#')) return null;
88	
89	    const absolutePath = decodeAbsolutePath(trimmedHref);
90	    if (absolutePath) {
91	        if (!absolutePath.toLowerCase().endsWith('.json')) return null;
92	
93	        const projectPath = projectPathFromAbsolutePath(absolutePath, projectRootPath);
94	        return projectPath ? projectTarget(projectPath, repositoryPaths) : { kind: 'local', path: absolutePath };
95	    }
96	    if (/^[a-z][a-z\d+.-]*:/iu.test(trimmedHref) || trimmedHref.startsWith('//')) return null;
97	
